using System;
using System.IO;
using System.Drawing;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using SplifyWin;
class HomeColumnsCheck {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;static int count;
 static void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS "+message);count++;}
 [STAThread]static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("MCRF_DATA_DIR",root);Environment.SetEnvironmentVariable("SPLIFY_WIN_DATA_DIR",root);Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_SETUP","1");Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_UPDATES","1");using(var form=new MainForm(false,false)){form.Show();Application.DoEvents();var state=(ClientState)typeof(MainForm).GetField("state",Flags).GetValue(form);state.AdvancedMode=true;UiTheme.Simple=true;SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"home"});foreach(var size in new[]{new Size(1050,680),new Size(1366,865),new Size(1400,900)}){form.Size=size;Application.DoEvents();var surface=form.Controls.Find("advancedHomeLayout",true).OfType<Panel>().Single();var left=form.Controls.Find("advancedHomeSummary",true).Single();var right=form.Controls.Find("advancedHomeSettings",true).Single();var server=form.Controls.Find("homeConnectionGroup",true).Single();var settings=form.Controls.Find("homeDiagnosticsCard",true).Single();Check(left.Top==right.Top&&left.Bottom==right.Bottom&&left.Right+16==right.Left,"equal-height side-by-side cards "+size);Check(!surface.AutoScroll&&!form.Controls.Find("advancedHomeScroll",true).Any(),"home has no scroll surface "+size);Check(server.Top==settings.Top&&server.Height==settings.Height&&server.Height<surface.Height,"matching card padding "+size);var controls=settings.Controls.Cast<Control>().Where(c=>c.Visible).ToArray();Check(controls.All(c=>c.Left>=20&&c.Top>=16&&c.Right<=settings.Width-20&&c.Bottom<=settings.Height-20),"settings fit padded card "+size+" card="+settings.Size+" outside="+String.Join(";",controls.Where(c=>c.Left<20||c.Top<16||c.Right>settings.Width-20||c.Bottom>settings.Height-20).Select(c=>c.Name+":"+c.Text+":"+c.Bounds)));var buttons=controls.OfType<Button>().ToArray();Check(buttons.All(a=>buttons.All(b=>a==b||!a.Bounds.IntersectsWith(b.Bounds))),"settings buttons do not overlap "+size);Check(form.Controls.Find("modePicker",true).Single().Parent==form.Controls.Find("homeServerCard",true).Single(),"mode remains in server card "+size);var overlay=(Panel)typeof(MainForm).GetField("popupOverlay",Flags).GetValue(form);using(var bitmap=new Bitmap(overlay.Width,overlay.Height)){overlay.DrawToBitmap(bitmap,new Rectangle(Point.Empty,overlay.Size));bitmap.Save(Path.Combine(root,"home-"+size.Width+".png"));}}form.Close();}Console.WriteLine("OK "+count+" checks");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
